using System;
using TMPro;
using UnityEngine;
using UnityEngine.Localization;

// Runtime binding for text generated by gameplay scripts.
// LocalizedString automatically responds to locale changes.
[DisallowMultipleComponent]
public sealed class GameTextBinding : MonoBehaviour
{
    private TMP_Text target;
    private LocalizedString localized;
    private string key;
    private object[] arguments;
    private bool subscribed;

    public static void Set(TMP_Text label, string entry, params object[] args)
    {
        if (label == null) return;
        var binding = label.GetComponent<GameTextBinding>();
        if (binding == null) binding = label.gameObject.AddComponent<GameTextBinding>();
        binding.Bind(label, entry, args);
    }

    private void Bind(TMP_Text label, string entry, object[] args)
    {
        if (target == label && key == entry && SameArguments(arguments, args)) return;
        Unsubscribe();
        target = label;
        key = entry;
        arguments = args;
        localized = new LocalizedString("GameTexts", entry) { Arguments = args };
        if (isActiveAndEnabled) Subscribe();
    }

    private static bool SameArguments(object[] a, object[] b)
    {
        if (a == b) return true;
        if (a == null || b == null || a.Length != b.Length) return false;
        for (int i = 0; i < a.Length; i++)
            if (!Equals(a[i], b[i])) return false;
        return true;
    }

    private void OnEnable() => Subscribe();
    private void OnDisable() => Unsubscribe();
    private void OnDestroy() => Unsubscribe();

    private void Subscribe()
    {
        if (localized == null || subscribed) return;
        subscribed = true;
        localized.StringChanged += Apply;
    }

    private void Unsubscribe()
    {
        if (localized == null || !subscribed) return;
        localized.StringChanged -= Apply;
        subscribed = false;
    }

    private void Apply(string value)
    {
        if (target != null) target.text = value;
    }
}
